void reverseString(std::string& s) {
    std::reverse(s.begin(), s.end());
}

int main() {
    std::string s;
    std::getline(std::cin, s);
    reverseString(s);
    std::cout << s << "\n";
    return 0;
}

#include <algorithm>
#include <iostream>
#include <string>

std::string addStrings(std::string a, std::string b) {
    std::string r;
    int i = (int)a.size() - 1, j = (int)b.size() - 1, carry = 0;
    while (i >= 0 || j >= 0 || carry) {
        int s = carry;
        if (i >= 0) s += a[i--] - '0';
        if (j >= 0) s += b[j--] - '0';
        r.push_back(char('0' + s % 10));
        carry = s / 10;
    }
    std::reverse(r.begin(), r.end());
    return r;
}

int main() {
    std::string a, b;
    std::getline(std::cin, a);
    std::getline(std::cin, b);
    std::cout << addStrings(a, b) << "\n";
    return 0;
}
